import{_ as a,c as r,o as t,ag as n}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Community Recommended Pathways/Technology Application Course","description":"","frontmatter":{"title":"Community Recommended Pathways/Technology Application Course"},"headers":[],"relativePath":"community/community-recommended-pathways-technology-application-course.md","filePath":"community/community-recommended-pathways-technology-application-course.md","lastUpdated":null}'),i={name:"community/community-recommended-pathways-technology-application-course.md"};function o(l,e,s,c,u,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="community-recommended-pathways-technology-application-course" tabindex="-1">Community Recommended Pathways/Technology Application Course <a class="header-anchor" href="#community-recommended-pathways-technology-application-course" aria-label="Permalink to &quot;Community Recommended Pathways/Technology Application Course&quot;">​</a></h1><h2 id="welcome-to-the-team" tabindex="-1">Welcome to the Team! <a class="header-anchor" href="#welcome-to-the-team" aria-label="Permalink to &quot;Welcome to the Team!&quot;">​</a></h2><p><strong>Congratulations</strong> on completing the Technology Application Course! We&#39;re thrilled about your enthusiasm and are here to help you make the most of it. This guide is a step-by-step plan to help you improve your skills and access the appropriate community resources.</p><h3 id="learning-and-development-pathways" tabindex="-1">Learning and Development Pathways <a class="header-anchor" href="#learning-and-development-pathways" aria-label="Permalink to &quot;Learning and Development Pathways&quot;">​</a></h3><ul><li><p><a href="https://cryptpad.irregularchat.com/diagram/#/2/diagram/edit/rTdjtIQKdkZqLvOKn3q+IV1P/" target="_blank" rel="noreferrer">Diagram</a>: Working graphical learning and community pathway.</p></li><li><p><a href="#">4856-Technology Application Course Grad.pdf</a>: A resource for leaders who need mentoring and skill development guidance.</p><ul><li>On NIPR you can download from inteldocs <a href="https://go.intelink.gov/5zXbEGU" target="_blank" rel="noreferrer">here</a>: <a href="https://go.intelink.gov/5zXbEGU" target="_blank" rel="noreferrer">https://go.intelink.gov/5zXbEGU</a></li></ul></li></ul><h3 id="immediate-actions-first-3-months" tabindex="-1">Immediate Actions (First 3 Months) <a class="header-anchor" href="#immediate-actions-first-3-months" aria-label="Permalink to &quot;Immediate Actions (First 3 Months)&quot;">​</a></h3><h3 id="_1-dive-into-practical-learning" tabindex="-1">1. Dive into Practical Learning <a class="header-anchor" href="#_1-dive-into-practical-learning" aria-label="Permalink to &quot;1. Dive into Practical Learning&quot;">​</a></h3><p><strong>a. Join Learning Platforms</strong></p><ul><li><p><strong>Hack The Box (HTB)</strong></p><ul><li><strong>Website</strong>: <a href="https://www.hackthebox.com" target="_blank" rel="noreferrer">Hack The Box</a></li><li><strong>Purpose</strong>: Practice ethical hacking in a safe environment.</li><li><strong>Steps</strong>:</li></ul></li><li><p>Sign up and start with retired machines, then progress to active challenges.</p></li><li><p><strong>TryHackMe (THM)</strong></p><ul><li><strong>Website</strong>: <a href="https://tryhackme.com" target="_blank" rel="noreferrer">TryHackMe</a></li><li><strong>Purpose</strong>: Guided lessons and labs in cybersecurity.</li><li><strong>Steps</strong>:</li></ul></li><li><p>Create an account, complete learning paths, and engage with the community.</p></li></ul><p><strong>b. Join the Purple Team Chat</strong></p><ul><li><p><strong>Purpose</strong>: Community and mentorship for Red and Blue team topics.</p></li><li><p><strong>Signal Group</strong>: Join the <a href="https://signal.group/#CjQKIFCSgs1LWgCGMbCzokVeypPIRU78xt5p9XzLozBgPafTEhCrL8EyIfHtTTM_8TA1GTHP" target="_blank" rel="noreferrer">Purple Team Signal Group</a> for networking and guidance.</p></li></ul><p><strong>c. Read Community Wiki Pages</strong></p><ul><li><p><a href="/cybersecurity/cyber-red-teaming.html">Cyber Red Teaming Wiki</a></p></li><li><p><a href="/general/dfp-guide.html">DFP Guide Wiki</a></p></li><li><p><a href="/general/certifications.html">Certifications Wiki</a></p></li></ul><p><strong>d. Engage with the Community</strong></p><ul><li><strong>Forum</strong>: <a href="https://forum.irregularchat.com/c/general/4" target="_blank" rel="noreferrer">Irregular Chat Forum</a> – Read tech posts and participate in discussions.</li></ul><h3 id="_2-start-self-paced-structured-learning" tabindex="-1">2. Start Self-Paced Structured Learning <a class="header-anchor" href="#_2-start-self-paced-structured-learning" aria-label="Permalink to &quot;2. Start Self-Paced Structured Learning&quot;">​</a></h3><ul><li><p><strong>Resource</strong>: <a href="/general/learning.html">DoD Funded Learning Materials</a></p></li><li><p><strong>Action</strong>: Begin courses at your own pace.</p></li></ul><h3 id="_3-set-up-your-home-lab" tabindex="-1">3. Set Up Your Home Lab <a class="header-anchor" href="#_3-set-up-your-home-lab" aria-label="Permalink to &quot;3. Set Up Your Home Lab&quot;">​</a></h3><p><strong>a. Choose Your Hardware</strong></p><ul><li><p>Options include PCs with virtualization software, SBCs like Raspberry Pi, and free cloud services.</p></li><li><p><strong>Specifications</strong>: Minimum 16GB RAM, multi-core processor.</p></li><li><p><a href="/general/virtual-environments.html">Virtual Environments Guide</a></p></li></ul><p><strong>b. Configure Virtual Machines (VMs)</strong></p><ul><li><p><strong>Windows Server VMs</strong>: Practice with Active Directory setups.</p></li><li><p><strong>Linux VMs</strong>: Use distributions like Ubuntu, Kali, Mint, DragonOS for learning.</p></li></ul><p><strong>c. Deploy Services Using Docker and Ansible</strong></p><ul><li><strong>Install Docker</strong>: Set up Docker on a Linux VM and deploy services like Pi-hole, Jellyfin, and Matrix.</li></ul><p><strong>d. Practice with Monitoring Tools</strong></p><ul><li><p><strong>Wazuh</strong>: Deploy for security monitoring.</p></li><li><p><strong>Security Onion</strong>: Set up for network security monitoring and intrusion detection.</p></li></ul><h3 id="_4-self-assessment-and-maintenance" tabindex="-1">4. Self-Assessment and Maintenance <a class="header-anchor" href="#_4-self-assessment-and-maintenance" aria-label="Permalink to &quot;4. Self-Assessment and Maintenance&quot;">​</a></h3><ul><li>Regularly assess your skills, document configurations, and maintain lab systems with updates and backups.</li></ul><h3 id="short-term-goals-3-6-months" tabindex="-1">Short-Term Goals (3-6 Months) <a class="header-anchor" href="#short-term-goals-3-6-months" aria-label="Permalink to &quot;Short-Term Goals (3-6 Months)&quot;">​</a></h3><h3 id="_1-advance-your-technical-skills" tabindex="-1">1. Advance Your Technical Skills <a class="header-anchor" href="#_1-advance-your-technical-skills" aria-label="Permalink to &quot;1. Advance Your Technical Skills&quot;">​</a></h3><ul><li>Build services (web, database, email) and simulate a small enterprise network.</li></ul><h3 id="_2-learn-programming-and-scripting" tabindex="-1">2. Learn Programming and Scripting <a class="header-anchor" href="#_2-learn-programming-and-scripting" aria-label="Permalink to &quot;2. Learn Programming and Scripting&quot;">​</a></h3><ul><li><p><strong>Python</strong>: Automate tasks and understand exploit code.</p></li><li><p><strong>Bash and PowerShell</strong>: Scripting for Linux and Windows.</p></li></ul><h3 id="_3-engage-in-collaborative-learning" tabindex="-1">3. Engage in Collaborative Learning <a class="header-anchor" href="#_3-engage-in-collaborative-learning" aria-label="Permalink to &quot;3. Engage in Collaborative Learning&quot;">​</a></h3><ul><li><p><strong>Participate in CTFs</strong>: Use <a href="https://ctftime.org" target="_blank" rel="noreferrer">CTFtime</a>, <a href="https://picoctf.org" target="_blank" rel="noreferrer">PicoCTF</a>, and <a href="https://overthewire.org" target="_blank" rel="noreferrer">OverTheWire</a>.</p></li><li><p><strong>Contribute to Open Source</strong>: Improve cybersecurity tools or share your own.</p></li></ul><h3 id="_4-expand-your-network" tabindex="-1">4. Expand Your Network <a class="header-anchor" href="#_4-expand-your-network" aria-label="Permalink to &quot;4. Expand Your Network&quot;">​</a></h3><ul><li><p><strong>General Tech Discussions</strong>: Join <a href="https://signal.group/#CjQKICEhFy25GcVHP90FAYQHnKVeDXYl_GfHaKb4VDzlc5v7EhBzGz_G4bPbBDsFDgX0XQdt" target="_blank" rel="noreferrer">Tech Chat (General)</a>.</p></li><li><p><strong>Special Interests</strong>: Join RF/SDR and AI/ML groups.</p></li></ul><h3 id="mid-term-goals-6-12-months" tabindex="-1">Mid-Term Goals (6-12 Months) <a class="header-anchor" href="#mid-term-goals-6-12-months" aria-label="Permalink to &quot;Mid-Term Goals (6-12 Months)&quot;">​</a></h3><h3 id="_1-obtain-professional-certifications" tabindex="-1">1. Obtain Professional Certifications <a class="header-anchor" href="#_1-obtain-professional-certifications" aria-label="Permalink to &quot;1. Obtain Professional Certifications&quot;">​</a></h3><ul><li><strong>TCM Security Courses</strong>: Enroll in PEH, PNPT, or CPTS for cybersecurity skills.</li></ul><h3 id="_2-lead-unit-initiatives" tabindex="-1">2. Lead Unit Initiatives <a class="header-anchor" href="#_2-lead-unit-initiatives" aria-label="Permalink to &quot;2. Lead Unit Initiatives&quot;">​</a></h3><ul><li>Develop training modules on phishing, OPSEC, and wireless surveying topics.</li></ul><h3 id="_3-coach-and-learn" tabindex="-1">3. Coach and Learn <a class="header-anchor" href="#_3-coach-and-learn" aria-label="Permalink to &quot;3. Coach and Learn&quot;">​</a></h3><ul><li>Mentor recent Technology Application Course grads, share your knowledge, and learn from them.</li></ul><h3 id="_4-specialize-in-an-area-of-interest" tabindex="-1">4. Specialize in an Area of Interest <a class="header-anchor" href="#_4-specialize-in-an-area-of-interest" aria-label="Permalink to &quot;4. Specialize in an Area of Interest&quot;">​</a></h3><ul><li>Options include Web Application Security, RF Security, Malware Analysis, and AI/ML.</li></ul><h3 id="long-term-goals-12-months" tabindex="-1">Long-Term Goals (12+ Months) <a class="header-anchor" href="#long-term-goals-12-months" aria-label="Permalink to &quot;Long-Term Goals (12+ Months)&quot;">​</a></h3><h3 id="_1-become-your-unit-s-master-trainer" tabindex="-1">1. Become Your Unit’s Master Trainer <a class="header-anchor" href="#_1-become-your-unit-s-master-trainer" aria-label="Permalink to &quot;1. Become Your Unit’s Master Trainer&quot;">​</a></h3><ul><li>Master concepts like OSCP and develop training tailored to your unit’s needs.</li></ul><h3 id="_2-innovate-and-contribute" tabindex="-1">2. Innovate and Contribute <a class="header-anchor" href="#_2-innovate-and-contribute" aria-label="Permalink to &quot;2. Innovate and Contribute&quot;">​</a></h3><ul><li>Research and develop new tools, mentor others, and contribute to knowledge sharing.</li></ul><h3 id="_3-become-a-mentor" tabindex="-1">3. Become a Mentor <a class="header-anchor" href="#_3-become-a-mentor" aria-label="Permalink to &quot;3. Become a Mentor&quot;">​</a></h3><ul><li>Guide new members, encourage growth, and provide constructive feedback.</li></ul><h3 id="_4-pursue-higher-education" tabindex="-1">4. Pursue Higher Education <a class="header-anchor" href="#_4-pursue-higher-education" aria-label="Permalink to &quot;4. Pursue Higher Education&quot;">​</a></h3><ul><li>Consider furthering education with a degree in cybersecurity or a related field.</li></ul><h3 id="additional-tips-for-success" tabindex="-1">Additional Tips for Success <a class="header-anchor" href="#additional-tips-for-success" aria-label="Permalink to &quot;Additional Tips for Success&quot;">​</a></h3><ul><li><p><strong>Ethical Conduct</strong>: Operate legally, respect privacy.</p></li><li><p><strong>Stay Curious and Adaptable</strong>: Embrace new challenges and reflect on learning.</p></li><li><p><strong>Balance and Well-being</strong>: Prioritize tasks, stay active, and avoid burnout.</p></li></ul><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><p>[Resources]</p>',59)])])}const g=a(i,[["render",o]]);export{p as __pageData,g as default};
